package com.primehr.performancemanagement;
import com.primehr.integration.administrative.*;import com.primehr.integration.humanresource.*;import com.primehr.performancemanagement.api.PerformanceCommitmentDtos.*;import com.primehr.performancemanagement.application.PerformanceCommitmentService;import com.primehr.performancemanagement.domain.*;import com.primehr.performancemanagement.infrastructure.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
@SpringBootTest@ActiveProfiles("test")@Transactional class PerformanceCommitmentCompositionIntegrationTest{
 @Autowired PerformanceCommitmentService commitments;@Autowired PerformancePolicyRepository policyRoots;@Autowired PerformancePolicyVersionRepository policyVersions;@Autowired PerformanceRatingScaleRepository scaleRoots;@Autowired PerformanceRatingScaleVersionRepository scaleVersions;@Autowired PerformanceSuccessIndicatorRepository indicatorRoots;@Autowired PerformanceSuccessIndicatorVersionRepository indicatorVersions;@Autowired PerformanceTemplateRepository templateRoots;@Autowired PerformanceTemplateVersionRepository templateVersions;@Autowired PerformanceTemplateSectionRepository templateSections;@Autowired PerformanceTemplateItemRepository templateItems;@Autowired PerformanceCycleRepository cycles;@Autowired PerformancePlanAssignmentRepository assignments;
 @MockBean HumanResourcePerformanceParticipantClient humanResource;@MockBean AdministrativePerformancePlanningClient administrative;
 @BeforeEach void authorities(){when(humanResource.get(anyLong(),anyString())).thenAnswer(x->new HumanResourceAssessmentSubject(x.getArgument(0),"E-"+x.getArgument(0),"Owner",true,100L,LocalDateTime.of(2025,1,1,8,0),20L,30L,"p".repeat(64),LocalDateTime.now(),Instant.now()));when(administrative.membership(anyLong(),anyString())).thenAnswer(x->new AdministrativePerformancePlanningClient.PersonnelMembership(x.getArgument(0),5L,"UNIT","Unit",7L,"Area",false,false,"MAIN","o".repeat(64),Instant.now()));}
 @Test void generationIsIdempotentSnapshotsDefinitionsAndTargetsReplaceAtomically(){String a="COMPOSE";Fixture f=fixture(a,10L,"E-10");CommitmentResponse first=commitments.generate(a,f.assignment().getId(),"request-1","E-10",PermissionDataScope.OWN_RECORDS,null);CommitmentResponse retry=commitments.generate(a,f.assignment().getId(),"request-2","E-10",PermissionDataScope.OWN_RECORDS,null);assertThat(retry.id()).isEqualTo(first.id());assertThat(first.sections()).singleElement().satisfies(s->{assertThat(s.weightPercent()).isEqualByComparingTo("100.0000");assertThat(s.items()).singleElement().satisfies(i->{assertThat(i.indicatorVersionId()).isEqualTo(f.indicator().getId());assertThat(i.indicatorFingerprint()).hasSize(64);assertThat(i.sourceRequiresEvidence()).isTrue();});});ItemResponse item=first.sections().get(0).items().get(0);assertThatThrownBy(()->commitments.replaceTargets(a,first.id(),new TargetReplacement(first.recordVersion(),List.of()),"Bearer x","E-10",PermissionDataScope.OWN_RECORDS,null)).hasMessageContaining("cover every");TargetInput target=new TargetInput(item.id(),new BigDecimal("25"),null,null,LocalDate.of(2026,1,1),LocalDate.of(2026,12,31),"Twenty-five completed outputs",null,"Planning basis","Certified quarterly MOV");CommitmentResponse updated=commitments.replaceTargets(a,first.id(),new TargetReplacement(first.recordVersion(),List.of(target)),"Bearer x","E-10",PermissionDataScope.OWN_RECORDS,null);assertThat(updated.contentRevision()).isGreaterThan(first.contentRevision());assertThat(updated.contentFingerprint()).isNotEqualTo(first.contentFingerprint());assertThat(commitments.readiness(a,updated.id(),"Bearer x","E-10",PermissionDataScope.OWN_RECORDS).ready()).isTrue();assertThatThrownBy(()->commitments.replaceTargets(a,first.id(),new TargetReplacement(first.recordVersion(),List.of(target)),"Bearer x","E-10",PermissionDataScope.OWN_RECORDS,null)).isInstanceOf(com.primehr.shared.exception.OptimisticConflictException.class);}
 @Test void ownershipPeriodsDirectionsAndUnapprovedCascadeSourcesFailClosed(){String a="COMPOSE-RULES";Fixture f=fixture(a,20L,"E-20");assertThatThrownBy(()->commitments.generate(a,f.assignment().getId(),"key","OTHER",PermissionDataScope.OWN_RECORDS,null)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);CommitmentResponse draft=commitments.generate(a,f.assignment().getId(),"key","E-20",PermissionDataScope.OWN_RECORDS,null);ItemResponse item=draft.sections().get(0).items().get(0);TargetInput outside=new TargetInput(item.id(),BigDecimal.ONE,null,null,LocalDate.of(2025,12,31),LocalDate.of(2026,12,31),null,null,null,null);assertThatThrownBy(()->commitments.replaceTargets(a,draft.id(),new TargetReplacement(draft.recordVersion(),List.of(outside)),"Bearer x","E-20",PermissionDataScope.OWN_RECORDS,null)).hasMessageContaining("within the cycle");CascadeInput edge=new CascadeInput(item.id(),item.id(),PerformanceCommitmentCascade.Mode.RESPONSIBILITY_SHARE,new BigDecimal("50"));assertThatThrownBy(()->commitments.replaceCascades(a,draft.id(),new CascadeReplacement(draft.recordVersion(),List.of(edge)),"E-20",PermissionDataScope.OWN_RECORDS,null)).hasMessageContaining("approved");assertThatThrownBy(()->new PerformanceCommitmentCascade(a,item.id(),item.id(),PerformanceCommitmentCascade.Mode.RESPONSIBILITY_SHARE,new BigDecimal("100.0001"),"f".repeat(64))).hasMessageContaining("100.0000");}
 private Fixture fixture(String a,Long employee,String no){PerformancePolicy pr=policyRoots.saveAndFlush(new PerformancePolicy(a,"P"));PerformancePolicyVersion policy=policyVersions.saveAndFlush(new PerformancePolicyVersion(a,pr.getId(),1,null,"Policy",null,"Basis","SPMS",PerformancePolicyVersion.Frequency.ANNUAL,false,false,false,false,false));policy.publish(LocalDate.of(2026,1,1),null,"test",Instant.now());policy=policyVersions.saveAndFlush(policy);PerformanceRatingScale sr=scaleRoots.saveAndFlush(new PerformanceRatingScale(a,"S"));PerformanceRatingScaleVersion scale=scaleVersions.saveAndFlush(new PerformanceRatingScaleVersion(a,sr.getId(),policy.getId(),1,null,"Scale",null,"Basis",BigDecimal.ONE,new BigDecimal("5"),2,RoundingMode.HALF_UP,PerformanceRatingScaleVersion.MeasureType.NUMBER,PerformanceRatingScaleVersion.Direction.HIGHER_IS_BETTER,PerformanceRatingScaleVersion.DimensionScoreSource.THRESHOLD_BAND));scale.publish(LocalDate.of(2026,1,1),null,"test",Instant.now());scale=scaleVersions.saveAndFlush(scale);PerformanceSuccessIndicator ir=indicatorRoots.saveAndFlush(new PerformanceSuccessIndicator(a,"I"));PerformanceSuccessIndicatorVersion indicator=indicatorVersions.saveAndFlush(new PerformanceSuccessIndicatorVersion(a,ir.getId(),policy.getId(),scale.getId(),1,null,"Indicator",null,"Output","KRA","KPI","Success",PerformanceRatingScaleVersion.MeasureType.NUMBER,"count",PerformanceRatingScaleVersion.Direction.HIGHER_IS_BETTER,BigDecimal.TEN,null,null,true,"MOV"));indicator.publish(LocalDate.of(2026,1,1),null,"test",Instant.now());indicator=indicatorVersions.saveAndFlush(indicator);PerformanceTemplate tr=templateRoots.saveAndFlush(new PerformanceTemplate(a,"IPCR"));PerformanceTemplateVersion template=templateVersions.saveAndFlush(new PerformanceTemplateVersion(a,tr.getId(),policy.getId(),scale.getId(),1,null,"IPCR",null,PerformanceTemplateVersion.FormType.IPCR,"Individual Commitment","Basis"));PerformanceTemplateSection section=templateSections.saveAndFlush(new PerformanceTemplateSection(a,template.getId(),PerformanceTemplateSection.Type.CORE,"CORE","Core",null,new BigDecimal("100.0000"),1));templateItems.saveAndFlush(new PerformanceTemplateItem(a,section.getId(),indicator.getId(),null,new BigDecimal("100.0000"),true,null,1));template.publish(LocalDate.of(2026,1,1),null,"test",Instant.now());template=templateVersions.saveAndFlush(template);PerformanceCycle cycle=cycles.saveAndFlush(new PerformanceCycle(a,"C","Cycle",LocalDate.of(2026,1,1),LocalDate.of(2026,12,31),policy.getId(),"Asia/Manila"));cycle.open("test","open",Instant.now());cycle=cycles.saveAndFlush(cycle);PerformancePlanAssignment assignment=assignments.saveAndFlush(new PerformancePlanAssignment(a,cycle.getId(),template.getId(),PerformancePlanAssignment.SubjectType.EMPLOYEE,employee,no,"Owner",7L,"Area",5L,"Unit",employee,no,"Owner",100L,20L,30L,"IPCR","o".repeat(64),"p".repeat(64),"r".repeat(64)));assignment.activate("test","activate",Instant.now());assignment=assignments.saveAndFlush(assignment);return new Fixture(indicator,assignment);}private record Fixture(PerformanceSuccessIndicatorVersion indicator,PerformancePlanAssignment assignment){}
}
